indexBufferCreateInfo.usageFlag = gfx::BufferUsageFlag::IndexBuffer;
indexBufferCreateInfo.size = static_cast<uint32_t>(indexBuffer.size() * sizeof(uint16_t));
indexBufferCreateInfo.initialData = as_bytes(toSpan(indexBuffer));
auto indexBufferHandle = gfx::create(indexBufferCreateInfo);
createInfo.indexBufferHandle = indexBufferHandle;
createInfo.indexType = IndexBufferTypeUInt16;
createInfo.indexCount = indexBuffer.size();

// Create a cluster. Two triangles define a face. Since a cube has six faces, you must create
// 36 indices (2 * 3 * 6 = 36). In this example, the entire mesh uses a single material, which
// is why you need only one cluster.
Mesh::CreateInfo::Cluster cluster(GraphicsPrimitiveTypeTriangles, indexBuffer.size(), material, materialUrl);
createInfo.clusters.push_back(cluster);
}

// Create a Box and set it as the bounding volume of the mesh.
// Position the box in the center of the mesh. Set the dimensions of the box along each axis
// to 2.0f, that is, from point (-1, -1, -1) to point (1, 1, 1) in the local coordinate space
// of the mesh.
createInfo.boundingBox = Box::fromCenterAndSize(Vector3(0.0f, 0.0f, 0.0f), Vector3(2.0f, 2.0f, 2.0f));

// Create a mesh from the data that you defined in the CreateInfo.
MeshSharedPtr mesh = Mesh::create(domain, createInfo, "box");

```
For details, see the `Mesh` class.

## Creating meshes with instancing¶
When you render a large number of copies of the same mesh, performing a draw call for each copy consumes GPU time and decreases application performance. Instancing makes it possible to draw multiple copies of a mesh with different attributes, such as position, size, and color, with a single render call.
This example renders four instances of a cube mesh at different locations and with different colors.
To create a cube mesh with instancing using the Kanzi Engine API:  
```
// Create a custom shader to use instanced attributes.
const char* vertexSource =
"#version 310 es\n"
"in vec3 kzPosition;\n"
"in vec3 InstancePosition;\n"
"in vec4 InstanceColor;\n"
"uniform highp mat4 kzProjectionCameraWorldMatrix;\n"
"out vec4 outColor;\n"
"void main() {\n"
"precision mediump float;\n"
"vec3 position = kzPosition + InstancePosition;\n"
"gl_Position = kzProjectionCameraWorldMatrix * vec4(position, 1.0);\n"
"outColor = InstanceColor;\n"
"}\n";

const char* fragmentSource =
"#version 310 es\n"
"in vec4 outColor;\n"
"layout(location = 0) out vec4 fragColor;\n"
"void main() {\n"
"precision lowp float;\n"
"fragColor = outColor;\n"
"}\n";

ShaderProgram::CreateInfo shaderCreateInfo;
{
auto compiler = kanzi::makeShaderCompiler();

gfx::ShaderFormat shaderFormat = gfx::ShaderFormat::Glsl43;
for (auto&& format : { gfx::ShaderFormat::VulkanSpirv13, gfx::ShaderFormat::GlslES30, gfx::ShaderFormat::Glsl33 })
{
if (gfx::isShaderFormatSupported(format))
{
shaderFormat = format;
break;
}
}

array<ShaderCompiler::ShaderSource, 2> sources;
sources[0].stage = gfx::ShaderStage::Vertex;
sources[0].source = vertexSource;

sources[1].stage = gfx::ShaderStage::Fragment;
sources[1].source = fragmentSource;

constexpr auto options = ShaderCompiler::OptionFlags::Default;
auto shaderResult = compiler->compile(sources, options, asSpan(shaderFormat), "");

shaderCreateInfo.addSourceShader(ShaderTypeVertex, toSpan(shaderResult.shaders[shaderFormat][gfx::ShaderStage::Vertex].blob));
shaderCreateInfo.addSourceShader(ShaderTypeFragment, toSpan(shaderResult.shaders[shaderFormat][gfx::ShaderStage::Fragment].blob));
if (shaderResult.info)
{
shaderCreateInfo.reflectionInfo = kanzi::move(shaderResult.info.value());
}
}

static const ShaderVertexAttribute kzPosition = ShaderVertexAttribute("kzPosition", VertexAttribute::SemanticPosition,
0, GraphicsElementTypeFLOAT, 0, 3, 0, 0);
static const ShaderVertexAttribute InstancePosition = ShaderVertexAttribute("InstancePosition", VertexAttribute::SemanticPosition,
1, GraphicsElementTypeFLOAT, 0, 3, 1, 0);
static const ShaderVertexAttribute InstanceColor = ShaderVertexAttribute("InstanceColor", VertexAttribute::SemanticColor,
0, GraphicsElementTypeFLOAT, 0, 4, 2, 0);
shaderCreateInfo.vertexFormat.push_back(kzPosition);
shaderCreateInfo.vertexFormat.push_back(InstancePosition);
shaderCreateInfo.vertexFormat.push_back(InstanceColor);

shaderCreateInfo.addFixedUniform("kzProjectionCameraWorldMatrix");

auto shader = ShaderProgram::create(domain, shaderCreateInfo, "CustomShader");
auto material = Material::create(domain, "CustomMaterial", shader);

// Define a CreateInfo structure and set it to not keep the data after uploading it to the GPU.
Mesh::CreateInfo createInfo;
createInfo.memoryType = GPUResource::GpuOnly;

// Describe the format for each vertex. In this example, every vertex has a position in 3D space,
// and every instance has a position in 3D space and a color.

// Add a three-component position to the vertex format description.
// Use the standard Kanzi name kzPosition.
MeshVertexAttribute position("kzPosition", VertexAttribute::SemanticPosition, 0, gfx::Format::RGB32_Float, ~0u);
createInfo.vertexFormat.attributes.push_back(position);

// Add instance position.
MeshVertexAttribute instancePosition("InstancePosition", VertexAttribute::SemanticPosition, 1, gfx::Format::RGB32_Float, 0);
instancePosition.divisor = 1;
createInfo.vertexFormat.attributes.push_back(instancePosition);

// Add instance color.
MeshVertexAttribute instanceColor("InstanceColor", VertexAttribute::SemanticColor, 0, gfx::Format::RGBA8_UNorm, 3 * sizeof(float));
instanceColor.divisor = 1;
createInfo.vertexFormat.attributes.push_back(instanceColor);

// Now that you added all components to the vertex format description, update the offsets,
// strides, and sizes.
createInfo.vertexFormat.updateSizesAndOffsets();

// Initialize index data.
createInfo.indexType = IndexBufferTypeUInt16;
createInfo.indexCount = 36;
createInfo.indexData.resize(createInfo.indexCount * sizeof(uint16_t));

// Create a cluster. Two triangles define a face. Since a cube has six faces, you must create
// 36 indices (2 * 3 * 6 = 36). In this example, the entire mesh uses a single material, which
// is why you need only one cluster.
Mesh::CreateInfo::Cluster cluster(GraphicsPrimitiveTypeTriangles, 36, material, "");
createInfo.clusters.push_back(cluster);

// Create the vertices. In this example, faces share vertices, so you need only eight vertices.
{
createInfo.vertexCount = 8;
// Define the positions of the cube corners.
// This example first defines the back face, then the front face.
const Vector3 cornerPositions[] = {
Vector3(1.0f, 1.0f, 1.0f),
Vector3(-1.0f, 1.0f, 1.0f),
Vector3(-1.0f, -1.0f, 1.0f),
Vector3(1.0f, -1.0f, 1.0f),
Vector3(1.0f, -1.0f, -1.0f),
Vector3(1.0f, 1.0f, -1.0f),
Vector3(-1.0f, 1.0f, -1.0f),
Vector3(-1.0f, -1.0f, -1.0f)
};

// Define vertex indices for all faces.
const uint16_t faceIndices[][4] = {
// Front.
{ 0, 1, 2, 3 },
// Right.
{ 5, 0, 3, 4 },
// Back.
{ 6, 5, 4, 7 },
// Left.
{ 1, 6, 7, 2 },
// Top.
{ 5, 6, 1, 0 },
// Bottom.
{ 3, 2, 7, 4 }
};

// To generate the vertex data, loop the data arrays that you defined above.
for (unsigned int face = 0; face < 6; ++face)
{
// Add two triangles.
uint16_t* indexData = reinterpret_cast<uint16_t*>(&createInfo.indexData[0]);
unsigned int faceBaseIndex = face * 6;

// The first three vertices of a face define the first triangle...
indexData[faceBaseIndex + 0] = faceIndices[face][0];
indexData[faceBaseIndex + 1] = faceIndices[face][1];
indexData[faceBaseIndex + 2] = faceIndices[face][2];

// ...and the second triangle uses the two last vertices of the face with the first vertex.
// These two triangles create a quad.
indexData[faceBaseIndex + 3] = faceIndices[face][2];
indexData[faceBaseIndex + 4] = faceIndices[face][3];
indexData[faceBaseIndex + 5] = faceIndices[face][0];
}

// Write vertices.
for (unsigned int vertexIndex = 0; vertexIndex < 8; ++vertexIndex)
{
// Write the correct vertex for this corner of each face.
writeVertexAttribute(createInfo, vertexIndex, 0, cornerPositions[vertexIndex]);
}
}

// Create the instance data: float position vector with three components and packed
// 32-bit color per instance.
{
// Create four instances of the cube.
createInfo.instanceCount = 4;
createInfo.instanceData.resize(createInfo.instanceCount * createInfo.vertexFormat.instanceSize);

// Define the positions.
const Vector3 instancePositions[] = {
Vector3(-1.0f, -1.0f, 0.0f),
Vector3(-1.0f, 1.0f, 0.0f),
Vector3(1.0f, 1.0f, 0.0f),
Vector3(1.0f, -1.0f, 0.0f)
};

// Define the colors: white, red, green, blue.
const uint32_t instanceColors[] = {
0xffffffff,
0xffff0000,
0xff00ff00,
0xff0000ff
};

byte* instanceBuffer = createInfo.instanceData.data();
for (unsigned instance = 0; instance < createInfo.instanceCount; ++instance)
{
// Copy the positions and colors to the instance data buffer.
auto pos = reinterpret_cast<float*>(instanceBuffer + instance * createInfo.vertexFormat.instanceSize);
*pos++ = instancePositions[instance].getX();
*pos++ = instancePositions[instance].getY();
*pos++ = instancePositions[instance].getZ();

auto color = reinterpret_cast<uint32_t*>(pos);
*color = instanceColors[instance];
}
}
// Create a Box and set it as the bounding volume of the mesh.
// Position the box in the center of the mesh. Set the dimensions of the box along each axis
// to 4.0f, that is, from point (-2, -2, -1) to point (2, 2, 1) in the local coordinate space
// of the mesh. This includes all the instances.
createInfo.boundingBox = Box::fromCenterAndSize(Vector3(0.0f, 0.0f, 0.0f), Vector3(4.0f, 4.0f, 2.0f));

// Create a mesh from the data that you defined in the CreateInfo.
MeshSharedPtr mesh = Mesh::create(domain, createInfo, "instancedBox");

```

## Decreasing the precision of a fragment shader¶
If fragment shading is a performance bottleneck, you can decrease the precision of the shader from full 32-bit floating point to 16-bit floating point. Many GPUs support operations at double rate when you decrease the precision.
To decrease the precision of a fragment shader:
1. In the Library, select Resource Files > Shaders and open the fragment shader whose precision you want to decrease.
The Shader Source Editor opens.
2. Declare variables with the appropriate precision qualifier:
| Precision qualifier  | Range  | Data type  | Examples of use  |
| --- | --- | --- | --- |
| `lowp`  |  (−2,2)  |  8-bit decimal. Modern GPUs do not have fixed point shader units and map this to 16-bit floating point. When you are not sure which precision to choose, prefer `mediump` over `lowp`.  | Colors in the RGB data range [0..1] and intensities in the range [0..1].  |
| `mediump`  |  (−215,215)  |  16-bit floating point with 1 sign bit, 5 bits of exponent, and 10 bits of mantissa. Some GPUs map this to 32-bit floating point.  | Colors, normals, textures, positions in object space.  |
| `highp`  |  (−2128,2128)  | 32-bit floating point with 1 sign bit, 8 bits of exponent, and 23 bits of mantissa.  | Matrices, large textures, positions in world space.  |
For example, for a fragment shader, use this code:  
```
#version 310 es

// lowp and mediump often double the performance compared to highp.
precision lowp float;

uniform sampler2D Texture;
uniform lowp float BlendIntensity;
in mediump vec2 vTexCoord;
layout(location = 0) out lowp vec4 fragColor;

void main()
{
vec4 color = texture(Texture, vTexCoord);
fragColor = color * BlendIntensity;
}

```
Do not use this code:  
```
#version 310 es

// Default to highp for everything.
precision highp float;
uniform sampler2D Texture;
uniform float BlendIntensity;
in vec2 vTexCoord;
layout(location = 0) out vec4 fragColor;

void main()
{
vec4 color = texture(Texture, vTexCoord);
fragColor = color * BlendIntensity;
}

```

## Moving calculations from pixel to vertex¶
Vertex shaders perform operations such as fetching vertices and calculating transformations. Kanzi executes a vertex shader once per vertex.
Fragment shaders perform operations such as getting texture data. Kanzi executes a fragment shader once per pixel.
Because a scene typically contains more pixels than vertices, fragment shaders execute more often than vertex shaders. For this reason, it is recommended to perform calculations in the vertex shader whenever possible, and pass the result to the fragment shader.
Use the vertex shader to calculate:
* Values that stay constant or that Kanzi calculates only a few times.
* Lighting calculations that can interpolate results between vertices without losing too much quality.
For example, in the Kanzi default VertexPhong material types, the vertex shader performs the lighting calculations. These material types offer higher performance than the FragmentPhong material types, whose fragment shader performs the lighting calculations.  
In this example, you create a simple material type that calculates the color of the material in the vertex shader.
To move calculations from pixel to vertex:
1. In the Library, press `Alt` and right-click Materials and Textures, and select Material Type.
Kanzi Studio creates a material type and a material that uses the material type.

2. In the material type that you created:
1. Replace the content of the Vertex Shader with this code:  
```
#version 310 es

in vec3 kzPosition;
uniform highp mat4 kzProjectionCameraWorldMatrix;
uniform lowp float counter;

out lowp vec4 vColor;

void main()
{
precision mediump float;

// Kanzi performs the trigonometric operations only for each vertex.
// For example, for a quad, which consists of two triangles that each
// have three vertices, that is six times.
vColor = vec4(cos(counter), sin(counter), 1, 1);

gl_Position = kzProjectionCameraWorldMatrix * vec4(kzPosition.xyz, 1.0);
}

```
2. Replace the content of the Fragment Shader with this code:  
```
#version 310 es

in lowp vec4 vColor;
layout(location = 0) out lowp vec4 fragColor;

void main()
{
precision lowp float;

// For each fragment, Kanzi applies a constant interpolated assignment with the
// same, lowp, precision. On most GPUs, this does not take longer than one cycle.
fragColor = vColor;
}

```
Do not use this code for the vertex shader:  
```
#version 310 es

in vec3 kzPosition;
uniform highp mat4 kzProjectionCameraWorldMatrix;

void main()
{
precision mediump float;

in vec3 kzPosition;
uniform highp mat4 kzProjectionCameraWorldMatrix;

void main()
{
precision mediump float;

// The vertex shader outputs the position and leaves the color calculation to the
// fragment shader. This is not a good idea when the number of fragments exceeds
// the number of vertices.
gl_Position = kzProjectionCameraWorldMatrix * vec4(kzPosition.xyz, 1.0);
}

```
Do not use this code for the fragment shader:  
```
#version 310 es

uniform lowp float counter;
layout(location = 0) out lowp vec4 fragColor;

void main()
{
precision lowp float;

// For each written fragment, Kanzi executes the trigonometric functions cos()
// and sin(). Trigonometric functions are expensive. Depending on the GPU, they
// can require several GPU cycles per fragment. The outcome is the same as when
// you store the result in a varying.
fragColor = vec4(cos(counter), sin(counter), 1, 1);
}

## Formatting log messages in code¶
A log message is either a scalar value or a format specification string followed by the format arguments.
For example:  
```
// Define a log category named "my category".
#define MY_LOG_CATEGORY KZ_LOG_CREATE_CATEGORY(KZ_LOG_ENABLED_CATEGORY, "my category")

// The log message is an integer constant.
kzLogInfo(MY_LOG_CATEGORY, (100));

// Log integer variable.
int length = 100;

// Output: 100
kzLogInfo(MY_LOG_CATEGORY, (length));

// Log a string literal.
// Output: Single log message.
kzLogInfo(MY_LOG_CATEGORY, ("Single log message."));

// Log a formatted message.
// Format string: "{} plus {} equals {}.".
// Format arguments: 1, 2, 1+2.
// Output: 1 plus 2 equals 3.
kzLogInfo(MY_LOG_CATEGORY, ("{} plus {} equals {}.", 1, 2, 1 + 2));

```
The format specification string is a literal text that can contain the format argument references in curly braces:
`"Text {...} text {...} ... {...} ..."`
When the logger writes the message, it replaces the argument references with a string representation of the values of the referred argument, and keeps the rest of the literal text unchanged. This is the structure of the format argument reference:
`{[argument index][:format specification]}`
The format argument index and format specification are optional.
Note
Place a colon ahead of the format specification part.
To prevent interpreting an opening brace ‘{’ as the format argument reference, prefix it with two backslashes: `\\{`
Note that if it is followed by a closing brace ‘}’, it is not removed and remains in the log message output. The sole string literal is not considered a format string and is not parsed for format argument references.
For example:  
```
// Log message consists of format string and one argument.
// Output: {} { some text }
kzLogInfo(MY_LOG_CATEGORY, ("\\{} \\{ {} } { this text is removed ", "some text"));

// Single string literals are not parsed as log message format string.
// Output: This text is string literal. Braces are kept {}, and { this text remains.
kzLogInfo(MY_LOG_CATEGORY, ("This text is string literal. Braces are kept {}, and { this text remains."));

```
The format argument index is a position of the format argument in the argument list. The first format argument has the index 0, followed by the argument with index 1, and so on. The last format argument has the index N-1, where N is the total number of the format arguments.
The format specification part of the format argument reference describes how to convert the referenced argument to the string when the reference is substituted with the string representation of the argument. See Log message argument format specification section for details.
When the log message is written, the format argument references found in the message format string are replaced with a string representation of the corresponding arguments.
In the simplest case the format arguments are referenced by empty braces **‘{}’** :  
```
// Format message arguments are referenced one by one using empty braces.
// Output: 1 2 3.
kzLogInfo(MY_LOG_CATEGORY, ("{} {} {}.", 1, 2, 3));

// Output: 1 plus 2 equals 3.
kzLogInfo(MY_LOG_CATEGORY, ("{} plus {} equals {}.", 1, 2, 1 + 2));

```
You can also reference the format arguments using the argument index explicitly:  
```
// Log values in custom order.
// Output: 3 1 2 3 5.
kzLogInfo(MY_LOG_CATEGORY, ("{2} {0} {1} {2} {4}.", 1, 2, 3, 4, 5));

// Log values in custom order using implicit argument indexing.
// Note: The argument reference '{1}' followed by '{}'.
// Output: argument #4 = 5, argument #0 = 1, argument #2 = 3, argument #3 = 4, argument #4 = 5.
kzLogInfo(MY_LOG_CATEGORY, ("argument #4 = {4}, argument #0 = {0}, argument #2 = {2}, argument #3 = {}, argument #4 = {}.", 1, 2, 3, 4, 5));

```
In the last example you can see that the indexed argument reference **‘{2}’** is followed by argument reference without index **‘{}’**. In such a case the argument referenced without index is the one (#3 in this case) following the argument referenced with index (#2 in this case).

// Using argument index could be shortened to:
// added in resulting text to octal or hexadecimal presentation.
// Output: decimal: 10, octal: 012, hexadecimal: 0xa.
kzLogInfo(MY_LOG_CATEGORY, ("decimal: {}, octal: {0:#o}, hexadecimal: {0:#x}.", 10));

// Field width is 4 characters.
// Output: decimal:  10.
kzLogInfo(MY_LOG_CATEGORY, ("decimal:{:4}.", 10));

// Field width is 4 characters, left aligned.
// Output: decimal:10  .
kzLogInfo(MY_LOG_CATEGORY, ("decimal:{:<4}.", 10));

// Field width is 4 characters, zero filled.
// Output: decimal:0010.
kzLogInfo(MY_LOG_CATEGORY, ("decimal:{:04}.", 10));

// Field width is 4 characters, with sign and left aligned.
// Output: decimal:+10 .
kzLogInfo(MY_LOG_CATEGORY, ("decimal:{:<+4}.", 10));

```
To use string format arguments:  
```
const char* message = "Hello world!!!";

// Write message to the log:
// Output: Message: Hello World!!!
kzLogInfo(MY_LOG_CATEGORY, ("Message: {}", string_view(message)));

// Write string literal to the log:
// Output: Message: String literal message.
kzLogInfo(MY_LOG_CATEGORY, ("Message: {}", "String literal message."));

```

## Creating a custom logger¶
To redirect log messages, you can implement a custom logger class, which inherits from `AbstractLogger`, and push the custom logger to the Kanzi logging system. Make your logger class override the `AbstractLogger::writeOverride` function.
To write log messages using your custom logger, use the `log.hpp::kzLog` macro.
If you want to use your custom logger to write all the application log messages, register the logger in the Default Logger (`DefaultLogger`). The Default Logger inherits from `AbstractLogger` and contains a chain of loggers through which every log message passes. These loggers are by default registered in the Default Logger:
| Default logger  | Destination of log messages  |
| --- | --- |
| `CoutLogger`  | Standard output  |
| `AndroidLogger`  | Android system log  |
| `Win32DebugLogger`  | Kanzi debug console on Windows  |
To implement a logger:  
```
// Use this logger to store log messages in a container for later retrieval.
//
// This class inherits from kanzi::AbstractLogger and implements the writeOverride() function. It stores logs in the container.
// To retrieve the logs, use the get() function.
class SimpleLogger : public AbstractLogger
{
public:
// Kanzi calls this function to write messages to the log.
//
// This function stores the log message in a container. To retrieve all log messages, use the get() function.
// Each log message includes:
// - The message text
// - The log level
// - The log category
// - If the message is an error, the file name and the line number where the error occured
//
// \param level The log level of the message.
// \param levelName The string representation of the log level.
// \param categoryName The string representation of the log category.
// \param fileName The name of the file in which the message originated.
// \param lineNumber The number of the line on which the message originated.
// \param message The message.
void writeOverride(LogLevel level, string_view levelName, string_view categoryName,
string_view fileName, size_t lineNumber, string_view message) override
{
// Start the log with the level name.
string logMessage(levelName);

// Separate the log level and the log category with a colon.
logMessage += ':';

// Add the category name.
logMessage.append(categoryName.data(), categoryName.length());

if (level == LogLevelError)
{
// The error is reported.
// To show where in the code the error was reported, add the file name and the line number to the message.
logMessage.append(fileName.data(), fileName.length());

// Separate the file name and the line number with a colon.
logMessage += ':';
logMessage += to_string(lineNumber);
}

// Add an angle bracket and the message text.
logMessage += "> ";
logMessage.append(message.data(), message.length());

// Append the log message to the log vector.
m_log.push_back(logMessage);
}

// Get log vector reference.
vector<string>& getLog()
{
return m_log;
}

private:
// Log vector.
vector<string> m_log;
};

```
To use a logger explicitly:  
```
// SimpleLogger inherits from kanzi::AbstractLogger and implements writeOverride.
SimpleLogger simpleLogger;

// Write a log message using SimpleLogger.
kzLog(simpleLogger, KZ_LOG_LEVEL_INFO, KZ_LOG_CATEGORY_GENERIC, ("Lets log 1 + 2 = {}.", 1 + 2));

```
To use a logger in logger chain:  
```
// SimpleLogger inherits from kanzi::AbstractLogger and implements writeOverride.
AbstractLoggerUniquePtr simpleLogger(new SimpleLogger());

// Before adding SimpleLogger to the logger chain, get the pointer to it.
// After you add SimpleLogger to the logger chain, the logger chain controls the lifetime of SimpleLogger.
SimpleLogger* simpleLoggerPtr = static_cast<SimpleLogger*>(simpleLogger.get());

// Push SimpleLogger to the logger chain. Now both SimpleLogger and the rest of the loggers handle every logged message.
DefaultLogger::pushLogger(kanzi::move(simpleLogger));

// Write a log message. SimpleLogger handles this message.
kzLogInfo(KZ_LOG_CATEGORY_GENERIC, ("Lets log 1 + 2 = {}.", 1 + 2));

```
To exclusively redirect log messages to a logger:  
```
// SimpleLogger inherits from kanzi::AbstractLogger and implements writeOverride.
AbstractLoggerUniquePtr simpleLogger(new SimpleLogger());

// Before adding SimpleLogger to the logger chain, get the pointer to it.
// After you add SimpleLogger to the logger chain, the logger chain controls the lifetime of SimpleLogger.
SimpleLogger* simpleLoggerPtr = static_cast<SimpleLogger*>(simpleLogger.get());

// Remove all default loggers from the logger chain. This way you make only SimpleLogger, which you push to the chain later, handle the logged messages.
DefaultLogger::popAllLoggers();

// Push SimpleLogger to the logger chain. Now only SimpleLogger handles every logged message.
DefaultLogger::pushLogger(kanzi::move(simpleLogger));

// Write a log message. SimpleLogger handles this message.
kzLogInfo(KZ_LOG_CATEGORY_GENERIC, ("Lets log 1 + 2 = {}.", 1 + 2));

```

### Registering a custom slogger2 buffer¶
Kanzi enables you to register a custom slogger2 buffer and pass it to a Kanzi application. Your Kanzi application then uses the buffer to write logs. For example, you can register a custom slogger2 buffer when you want to give the buffer a custom name or if you want to set any of the properties from the `slog2_buffer_set_config_t` structure passed to `slog2_register`.
When you register a slogger2 buffer, slogger2 ignores all the other QNX logger configuration parameters that you set in an `application.cfg` or `Application::onConfigure`.
Keep in mind that -1 and null are not valid values for the slogger2 buffer name.
To register a custom slogger2 buffer, in `Application::onConfigure` set:  
```
configuration.slog2Config.customSlog2Buffer = value

```
where `value` is a `slog2_buffer_t` type buffer. The default value is nullptr (disabled).
For example, you can register a custom slogger2 buffer like this:  
```
// Register one slog2_buffer_t buffer.
vector<slog2_buffer_t> buffers = vector<slog2_buffer_t>(1);

slog2_buffer_set_config_t buffersetConfig{ 1, "MyBufferset", SLOG2_INFO, {{ "MyBuffer", 16 }}, UINT32_MAX };

if (slog2_register(&buffersetConfig, buffers.data(), 0) != 0)
{
// Handle the error.
}

// Pass the registered buffer to the application.
configuration.slog2Config.enabled = true;
configuration.slog2Config.customSlog2Buffer = buffers[0];

```

### Cleaning up after slogger2¶
When your Kanzi application quits, slogger2 by default calls `slog2_reset`. This frees all the slogger2 buffers registered by a Kanzi process, not just the one registered by Kanzi. You can change this behavior by overriding `Application::uninitializePlatform`. For example, change this behavior when you want to call `slog2_reset` after a Kanzi application quits.  
```
class MyApplication : public Application
{

...

public:

...

// Override the uninitializePlatform method to prevent calling slog2_reset.
void uninitializePlatform() final
{

...

}
}

```

```
* In the `Application::onConfigure` function:  
```
configuration.performanceInfoProperties.graphFilter = "TickAnimations;Render";

```
See PerformanceInfoGraphFilter.
5. (Optional) Set the colors that Kanzi uses to draw the Performance HUD:
1. In Visual Studio in the file where you want to set the colors, include the `performance_info.hpp` header file.
For example, to set the colors that Kanzi uses to draw the Performance HUD of the Scroll view example, in the `scroll_view.cpp` file add:  
```
#include <kanzi/core.ui/application/performance_info.hpp>

```
2. Set the colors that Kanzi uses to show the Performance HUD graph frames, graph data, and text.
For example, in the `scroll_view.cpp` file in the `Application::onProjectLoaded` function add:  
```
// Get the performanceInfo object. If the object does not exist, create it.
PerformanceInfo& performanceInfo = acquirePerformanceInfo();
// Set the color of graph frames to gray.
performanceInfo.setBorderColor(ColorRGBA(0.5f, 0.5f, 0.5f));
// Set the color of graph data to yellow.
performanceInfo.setLineColor(ColorRGBA(1.0f, 1.0f, 0.0f));
// Set the color of text to black.
performanceInfo.setFontColor(ColorRGBA(0.0f, 0.0f, 0.0f));

```
6. Build and run your application. See Deploying Kanzi applications.
To show the performance graphs, you must use the Profiling build of Kanzi.
For example, on Windows build your application in Visual Studio using the Profiling build configuration.

When you run the application, the Performance HUD shows the performance measurement graphs.
If you do not see the graphs, make the application window larger.

### Logging data from a profiler registry¶
You can log data from all profilers registered in a specific profiler registry by iterating through the profilers and calling the `AbstractProfiler::logAggregateData` or `AbstractProfiler::logAllData` function.
For example, to log a summary of performance profiling data from your custom profiler when exiting the application:  
```
// Kanzi calls this function when the application exits.
void onShutdown() override
{
// Get the default profiler registry.
const auto& registry = kzProfilingGetDefaultRegistry();

// Go through all profilers in the registry and log their aggregate data.
for (auto profilerIter = registry.beginProfilers(),
profilerIterEnd = registry.endProfilers();
profilerIter != profilerIterEnd; ++profilerIter)
{
(*profilerIter)->logAggregateData();
}
}

```

## Creating performance profiling categories¶
To group the performance measurements of functions and scopes, create your own performance profiling categories.
To create a performance profiling category, use the `ProfilingMacros::kzProfilingCreateCategory` macro to define the category and the `ProfilingMacros::kzProfilingRegisterCategory` macro to register the category.
For example:  
```
// Define a performance profiling category MY_PROFILING_CATEGORY.
// Set the compile-time state of the category to enabled, name the category ``MyProfilingCategory``,
// and set the sample buffer size of the category to 200.
#define MY_PROFILING_CATEGORY kzProfilingCreateCategory(KZ_PROFILING_ENABLED_CATEGORY, "MyProfilingCategory", 200)
// Register the performance profiling category MY_PROFILING_CATEGORY and set its initial runtime state to enabled.
// The runtime state of a performance profiling category controls whether profilers in the category collect samples.
// You can control the runtime state of performance profiling categories in the application configuration.
kzProfilingRegisterCategory(MY_PROFILING_CATEGORY, KZ_PROFILING_ENABLED_CATEGORY);

```
See ProfilingCategoryFilter.
You can use the performance profiling category you created to profile the performance of:
* Scopes. See Measuring the performance of scopes.
* Functions. See Measuring the performance of functions.

## Measuring the performance of scopes¶
You can use Kanzi profiling macros to measure the execution time of any scope in your application code:
* `ProfilingMacros::kzProfileScope` profiles the execution time of a scope.
* `ProfilingMacros::kzProfileScopeExtended` profiles the execution time of a scope using a custom profiler registry and sample buffer size.  
To measure the performance of a scope:
1. (Optional) Create your own performance profiling category. See Creating performance profiling categories.
If you do not want to create a performance profiling category, you can use the Generic category `ProfilingMacros::KZ_PROFILING_CATEGORY_GENERIC`.
2. In the beginning of the scope the performance of which you want to measure, call the `ProfilingMacros::kzProfileScope` macro.
The `ProfilingMacros::kzProfileScope` macro creates a profiler and registers the profiler in the Default Profiler Registry. Every time the scope is entered, Kanzi adds to the profiler a new sample which includes the time spent executing this scope.
For example, to measure the execution time of the `if (!m_interpolationActive)` block in the Scroll view example:  
```
// Activate interpolation playback by adding it to the code.
if (!m_interpolationActive)
{
// kzProfileScope() measures the time it takes to execute this scope.
// The profiler created by kzProfileScope() is assigned to the KZ_PROFILING_CATEGORY_GENERIC category and registered in the Default Profiler Registry.
// The name of the profiler is "Activate interpolation playback".
// Every time this scope is entered, that is when "!m_interpolationActive" is true, Kanzi adds a new sample to the profiler.
kzProfileScope(KZ_PROFILING_CATEGORY_GENERIC, "Activate interpolation playback");
getDomain()->getRootTimelineClock()->addTimelinePlayback(m_interpolationPlayback);
m_interpolationActive = true;
}

## Measuring the performance of functions¶
You can use the `ProfilingMacros::kzProfileFunction` macro to measure the execution time of functions in your application code.
To measure the performance of a function:
1. (Optional) Create your own performance profiling category. See Creating performance profiling categories.
If you do not want to create a performance profiling category, you can use the Generic category `ProfilingMacros::KZ_PROFILING_CATEGORY_GENERIC`.
2. In the beginning of the function the performance of which you want to measure, call the `ProfilingMacros::kzProfileFunction` macro.
The `ProfilingMacros::kzProfileFunction` macro creates in this function a static profiler and registers the profiler in the Default Profiler Registry. Every time the function is called, Kanzi adds to the profiler a new sample which includes the time spent executing this function.
For example, to measure the performance of scrolling in the Scroll view example, call the `ProfilingMacros::kzProfileFunction` macro in the handler for the `ScrollViewConcept::ScrolledMessage` message.  
```
// Handler for the ScrollView3D::ScrolledMessage message from the Scroll View node.
// Updates input values for the zoom animation.
auto scrollToken = m_scrollView->addMessageHandler(ScrollView3D::ScrolledMessage, this {
// kzProfileFunction() measures the time it takes to execute the function.
// The profiler created by kzProfileFunction() is assigned to the KZ_PROFILING_CATEGORY_GENERIC category and registered in the Default Profiler Registry.
// The name of the profiler is provided by the compiler and includes the name of this function. See KZ_PROFILING_THIS_FUNCTION_NAME.
// Every time the function is called, Kanzi adds a new sample to the profiler.
kzProfileFunction(KZ_PROFILING_CATEGORY_GENERIC);

...
}

## Logging resource profiling data¶
To analyze the loading and deployment of resources in your Kanzi application, log the resource profiling data. Before you can log resource profiling data you must enable resource profiling. See Enabling resource profiling.
After you enable resource profiling, Kanzi profiles the loading and deployment of each resource in your application and stores the profiling data in the resource profiler. Implement the logging of the collected profiling data in your application code. Kanzi provides the `ResourceProfilingPtreePopulator` class which you can use to populate a Boost property tree with resource profiling data. You can then log the profiling data in JSON format using the JSON formatter available in Boost.
To log resource profiling data:
1. In your application code include the header files that are needed to log resource profiling data.  
```
// Defines the standard input/output stream objects.
#include <kanzi/core/cpp/iostream.hpp>
// Provides classes that implement string stream input/output operations.
#include <kanzi/core/cpp/sstream.hpp>
// Provides the functionality for populating a Boost property tree with resource profiling data.
#include <kanzi/core.ui/resource/resource_profiling_ptree_populator.hpp>
// Provides the functionality for translating a Boost property tree to JSON and writing it to a file.
#include <boost/property_tree/json_parser.hpp>

```
2. Add to your application the code that outputs resource profiling data.
For example, to log profiling data to `cout` in the callback `Application::onShutdown` which Kanzi calls on application exit, add this code:  
```
void onShutdown() override
{
// Populate the Boost property tree with resource profiling data.
ptree resourceProfilingDataTree = ResourceProfilingPtreePopulator::populatePropertyTree(getResourceManager()->getResourceProfiler());
// Write the property tree to string stream in JSON format.
stringstream ss;
boost::property_tree::json_parser::write_json(ss, resourceProfilingDataTree);
// Boost json_writer considers "/" to be an escape character and adds "\" before each "/".
// This affects how kzb URLs are displayed.
// This code outputs json to cout replacing "\/" with "/".
string str(ss.str());
string_view strView(str);
while (!strView.empty())
{
size_t backSlashPos = strView.find("\\/");
if (backSlashPos == string_view::npos)
{
cout << strView;
strView = string_view();
continue;
}
cout << strView.substr(0, backSlashPos);
strView = strView.substr(backSlashPos + 1);
}
cout << "\n";
}

```
3. Build your application using one of the Profiling build configurations and run your application. You can see the profiling data in the console window when you exit the application.
To build and run your application on Windows:
1. In Visual Studio build your application using the Profiling build configuration.

2. When you are running the Kanzi Profiling build on Windows, there is no console window. To log resource profiling data, open the command line interface on your computer and run the application so that you redirect the application output to a file where you want to store the resource profiling information:  
```
Application\build_vs<Version>\runtime\Profiling\My_application.exe > MyApplicationResourceProfiling.json

## Reacting to application lifecycle events¶  
### Adding startup logic¶
You can define the startup logic of your application in these functions:
* Kanzi calls the `Application::onStartup` function once, immediately after starting the application, but before it loads the initial UI contents. Here you can add application start-up logic that requires modifying already initialized Kanzi objects.
* Kanzi calls the `Application::onProjectLoaded` function once, immediately after loading the initial UI contents.
Usually you insert here initialization code that depends on the content that has already been loaded. For example, you can attach initial message handlers or listeners, populate the UI with data, and so on.
For example, this code attaches a handler to a Button after Kanzi loads the node tree:  
```
void onProjectLoaded() override
{
// Get reference to the Screen node.
ScreenSharedPtr screen = getScreen();
kzAssert(screen);

// Look up reference to a button by alias.
Button2DSharedPtr button = screen->lookupNode<Button2D>("#Button");
kzAssert(button);

// Attach a handler to the button.
button->addMessageHandler(Button2D::ClickedMessage, this
{
this->buttonHandler(arguments);
});
}

```
This diagram shows the callbacks for startup and shutdown logic.

### Observing application state¶
You can observe the application state to find out whether an application is running, minimized, or suspended.
A Kanzi application is always in one of these states:
* `MainLoopState::Running` state. This is the normal mode of operation of a Kanzi application. This is the initial state of an application.
* `MainLoopState::Paused` state. The platform can impose rules on application behavior when it is out of focus or minimized. To mark such state, a platform backend can set the application to the `MainLoopState::Paused` state.
In this state, Kanzi stops normal input handling and rendering, and waits to be put back to the `MainLoopState::Running` state. Additionally, it is typical for applications to halt heavy work when in this state.
* `MainLoopState::Quitting` state. This state indicates that either application or the platform requested the application to quit by calling `MainLoopScheduler::quit`. In this state, applications must avoid starting work, unless that work is related to uninitialization.  
This diagram shows the states of a Kanzi application.

To find out the application state, call `MainLoopScheduler::getState`.
For example, to prevent adding a task when an application is quitting:  
```
void doSomethingRepeatedly()
{
doSomething();

// If a condition is met...
if (someCondition() &&
// ...and the application is not quitting...
getState() != MainLoopState::Quitting)
{
// ...add another task to the task dispatcher.
getDomain()->getTaskDispatcher()->submit(this
{
this->doSomethingRepeatedly();
});
}
}

```

### Adding recurring tasks¶
When you want Kanzi to execute a task every frame, you can add it to any stage of the main loop using `MainLoopScheduler::appendTask` and `MainLoopScheduler::prependTask`, with option `MainLoopScheduler::TaskRecurrence::Recurring`.
For example, you can use a recurring task to call the update function of an external library:
C++  
```
void onStartup() override
{
// From the main loop Animate stage, tick an external physics engine.
getMainLoopScheduler().appendTask(AnimateStage,
kzMakeFixedString("TickPhysics"),
MainLoopScheduler::TaskRecurrence::Recurring,
this
{
this->getPhysicsEngine()->tick(deltaTime);
});
}

```
Java  
```
void onStartup()
{
// From the main loop Animate stage, tick an external physics engine.
MainLoopScheduler mls = getDomain().getMainLoopScheduler();
mls.appendTask(MainLoopScheduler.AnimateStage, "TickPhysics", TaskRecurrence.Recurring,
new MainLoopScheduler.Task() {
@Override
public void handle(Duration lastFrameDuration)
{
getPhysicsEngine().tick(lastFrameDuration);
}
});
}

```
Kotlin  
```
fun onStartup() {
// From the main loop Animate stage, tick an external physics engine.
domain.mainLoopScheduler.appendTask(
MainLoopScheduler.AnimateStage, "TickPhysics", TaskRecurrence.Recurring
) { lastFrameDuration -> getPhysicsEngine().tick(lastFrameDuration) }
}

```

### Adding one-time tasks¶
When you want Kanzi to execute a task only once, you can add it to any stage of the main loop using `MainLoopScheduler::appendTask` and `MainLoopScheduler::prependTask`, with recurrence option `MainLoopScheduler::TaskRecurrence::OneTime`.
For example, to capture a screen shot of the output when the user presses the `Enter` key:
C++  
```
void onKeyInputEvent(const KeyEvent& keyEvent) override
{
// First invoke the base class implementation.
Application::onKeyInputEvent(keyEvent);

// If the user presses the Enter key:
if (keyEvent.getKeyUp() == LogicalKey::Enter)
{
// Force re-rendering.
getScreen()->invalidateDraw();

// Add a post-rendering task to capture the screen output.
getMainLoopScheduler().appendTask(RenderStage,
kzMakeFixedString("CaptureScreenshot"),
MainLoopScheduler::TaskRecurrence::OneTime,
this
{
this->captureScreen();
});
}
}

```
Java  
```
@Override
public boolean onKeyUp(int keyCode)
{
boolean handled = super.onKeyUp(keyCode);

if (keyCode == KeyEnter)
{
// Force re-rendering.
getScreen().invalidateDraw();

// Add a post-rendering task to capture the screen output.
MainLoopScheduler mls = getDomain().getMainLoopScheduler();
mls.appendTask(MainLoopScheduler.RenderStage, "CaptureScreenshot",
TaskRecurrence.OneTime, new MainLoopScheduler.Task() {
@Override
public void handle(Duration lastFrameDuration)
{
captureScreen();
}
});
}

return handled;
}

```
Kotlin  
```
override fun onKeyUp(keyCode: Int): Boolean {
val handled = super.onKeyUp(keyCode)
if (keyCode == KeyEnter) {
// Force re-rendering.
screen.invalidateDraw()

// Add a post-rendering task to capture the screen output.
domain.mainLoopScheduler.appendTask(
MainLoopScheduler.RenderStage, "CaptureScreenshot",
TaskRecurrence.OneTime
) { captureScreen() }
}
return handled
}

```

### Overriding tasks¶
When you want to modify the default approach that Kanzi uses to process input, performs layout and renders content, update the screen, and perform other repeating tasks, you can replace existing tasks using `MainLoopScheduler::replaceTask`.
For example, you can override the default rendering to apply a custom post-processing effect in the code. You can achieve this by first rendering the contents to an off-screen texture with the default rendering implementation, and then rendering that texture to the screen with a post-processing shader:  
```
// An off-screen texture to hold the rendering result before applying the post-processing effect.
TextureSharedPtr m_offscreenTexture;

// A material that applies a full-screen post-processing effect in the fragment shader.
MaterialSharedPtr m_postProcessMaterial;

/// Brush for rendering the post-processing effect.
MaterialBrushSharedPtr m_brush;

/// Brush renderer for post-processing effect.
BrushRendererPtr m_brushRenderer;

/// Quad geometry for post-processing effect.
GeometrySharedPtr m_geometry;

void onProjectLoaded() override
{
// Create a framebuffer for off-screen rendering.
m_offscreenTexture = createOffscreenTexture();

// Acquire a material for applying a post-processing effect.
m_postProcessMaterial = createPostProcessMaterial();

// Construct a brush for the post-processing effect.
m_brush = MaterialBrush::create(getDomain(), "Effect Brush");

// Construct a Brush Renderer for the brush.
m_brushRenderer = m_brush->createBrushRenderer(nullptr);

// Attach the post-processing material to the brush renderer.
m_brushRenderer->attachMaterial(m_postProcessMaterial);

// Get the unit geometry.
m_geometry = getUnitQuadGeometry(getDomain());

// Get the token of the default rendering task from the render stage.
auto& scheduler = getMainLoopScheduler();
auto tasks = scheduler.getTaskInfo(RenderStage);
auto itTask = find_if(cbegin(tasks), cend(tasks), 
{
return taskInfo.name == "Render";
});
kzAssert(itTask != cend(tasks));
auto token = itTask->token;

// Replace the default rendering task with a custom implementation.
scheduler.replaceTask(RenderStage,
token,
this
{
// Set the offscreen texture as the rendering target.
this->setRootCompositionTarget(this->m_offscreenTexture);

// Render to the off-screen texture using the default rendering logic.
this->render();

// Revert offscreen texture.
this->setRootCompositionTarget(nullptr);

// Render the texture to the screen with the post-processing effect applied.
this->renderPostProcessed();

// Mark the current frame as rendered.
this->getMainLoopScheduler().setCurrentFrameRendered();
});
}

// Mark the current frame as rendered.
this->getMainLoopScheduler().setCurrentFrameRendered();
});
}

TextureSharedPtr createOffscreenTexture()
{
// Get the off-screen texture size from the window size.
// This assumes that the window size does not change during runtime.
auto graphicsOutput = getGraphicsOutput();
auto width = graphicsOutput->getWidth();
auto height = graphicsOutput->getHeight();

// Create a render target with color and depth attachments.
auto createInfo = Texture::CreateInfoRenderTarget(width, height, GraphicsFormatR8G8B8A8_UNORM);
createInfo.depthStencilFormat = GraphicsFormatD16_UNORM;
auto texture = Texture::create(getDomain(), createInfo, "Offscreen Texture");
return texture;
}

MaterialSharedPtr createPostProcessMaterial()
{
// Acquire a custom post-processing effect.
// Note that the default textured debug material copies the texture to the screen without any effect.
return Material::acquireMaterialTextured(*getResourceManager());
}

void renderPostProcessed()
{
auto& renderer = *getRenderer();
auto graphicsOutput = getGraphicsOutput();
auto& compositionStack = renderer.getCompositionStack();

// Set the active graphics output as the render target.
compositionStack.pushCompositionActiveGraphicsOutput();
compositionStack.pushDefaultSettings2D();

// Set the off-screen texture and other shader inputs for the post-processing material.
m_postProcessMaterial->setTexture(StandardMaterial::TextureProperty, m_offscreenTexture);

// Bind the brush renderer.
m_brushRenderer->bind(renderer);

// Set a default orthographic projection.
{
Matrix4x4 projectionMatrix = Matrix4x4::createOrthogonalProjection(-1.0f, 1.0f, -1.0f, 1.0f, -1.0f, 1.0f);
Matrix4x4 cameraMatrix;
cameraMatrix[14] = 0.5f;
renderer.setMatrix(FixedMatrixProjection, projectionMatrix);
renderer.setMatrix(FixedMatrixCamera, cameraMatrix);
}

// Render the texture as a full-screen quad.
auto transform = getUnitQuadTargetTransformation(Vector2(-1.0f, -1.0f), Vector2(2.0f, 2.0f));
m_brushRenderer->draw(renderer, *m_geometry, transform);

// Remove composition target from the composition stack.
compositionStack.popSettings();
compositionStack.popComposition();
}

```
As an alternative to individually replacing tasks, you can redefine the whole main loop, by overriding `Application::initializeMainLoopTasks`. Kanzi attaches the default main loop tasks in this function. To allow copying, its implementation is intentionally exposed in the header.

### Adding timers¶
When you want Kanzi to execute a task at regular time intervals, you can add the task before a stage of the main loop using `MainLoopScheduler::prependTimer` and after a stage of the main loop using `MainLoopScheduler::appendTimer`.
Use timer recurrence options to execute a timer only once (`MainLoopScheduler::TaskRecurrence::OneTime`) or repeatedly (`MainLoopScheduler::TaskRecurrence::Recurring`). When a recurring timer elapses multiple times in a single iteration of the Kanzi main loop, Kanzi executes that timer only once.
C++  
```
using TimerTask = function<void(chrono::nanoseconds, unsigned int)>;

```
Java  
```
public interface TimerTask {
void handle(Duration elapsedDuration, int repeatCount);
}

```
Kotlin  
```
interface TimerTask {
fun handle(elapsedDuration: Duration?, repeatCount: Int)
}

```
When Kanzi executes a timer, it passes as arguments:
* The elapsed duration rounded down to a multiple of the interval of the timer
* The number of elapsed intervals  
For example, to update time on a clock using a recurring timer:
C++  
```
void activateClock()
{
// Add a recurring timer task that updates the clock once every second.
m_clockTimer = getMainLoopScheduler().appendTimer(UserStage,
kzMakeFixedString("Clock"),
MainLoopScheduler::TimerRecurrence::Recurring,
chrono::seconds(1),
this
{
this->updateClock(elapsedDuration * repeatCount);
});
}

void deactivateClock()
{
// Remove the clock timer.
getMainLoopScheduler().removeTimer(m_clockTimer);
}

```
Java  
```
void activateClock()
{
MainLoopScheduler mls = getDomain().getMainLoopScheduler();

// Add a recurring timer task that updates the clock once every second.
mClockTimer = mls.appendTimer(MainLoopScheduler.UserStage, "Clock",
TimerRecurrence.Recurring, Duration.ofSeconds(1), new MainLoopScheduler.TimerTask() {
@Override
public void handle(Duration elapsedDuration, int repeatCount)
{
updateClock(elapsedDuration.multipliedBy(repeatCount));
}
});
}

void deactivateClock()
{
MainLoopScheduler mls = getDomain().getMainLoopScheduler();
// Remove the clock timer.
mls.removeTimer(mClockTimer);
}

```
Kotlin  
```
fun activateClock() {
// Add a recurring timer task that updates the clock once every second.
mClocktimer = domain.mainLoopScheduler.appendTimer(
MainLoopScheduler.UserStage, "Clock",
TimerRecurrence.Recurring, Duration.ofSeconds(1)
) { elapsedDuration, repeatCount -> updateClock(elapsedDuration.multipliedBy(repeatCount.toLong())) }
}

fun deactivateClock() {
// Remove the clock timer.
domain.mainLoopScheduler.removeTimer(mClocktimer)
}

```

## Balancing between UI responsiveness and resource loading¶
The memory that is required to contain all of the application resources can exceed the amount of RAM on your target device. You can break down your application into parts and define the navigation so that only some parts are loaded at the same time.
When your application navigates to a part, Kanzi receives a request to load the required resources. You can tell Kanzi to load these resources in loader threads instead of the UI thread. This way you can preserve the responsiveness of your application while Kanzi loads the resources.
While resources can be loaded in the loader threads, OpenGL requires that the GPU resources, such as textures, meshes, and materials are deployed in the UI thread where the resources are copied to the GPU memory.
Kanzi keeps the resources that it must deploy in a queue and by default deploys only one resource each frame. This way Kanzi keeps the UI responsive but can take longer to deploy the application resources.
You can use the `DeploymentQueueBudget` application configuration and keep loading resources each frame until the configured time period elapses. When your application must deploy many small resources, time budget greater than 0 can significantly decrease the time to deploy all resources.
You can define your own deployment logic by overriding the `Application::progressDeploymentQueueOverride`. Use the knowledge of the assets of your application or its execution environment to modify the behavior to deploy a different number of resources on a per-frame basis.
For example, when your application contains a lot of large resources, the default implementation of deploying one resource every frame can cause uneven framerate. When you define your own deployment logic you can throttle the deployment of resources:  
```
void progressDeploymentQueueOverride() override
{
ResourceManager* resourceManager = getResourceManager();

// Deploy once and check whether any items remain in the queue.
while (resourceManager->processDeploymentQueueItem() &&
// Check whether conditions exists to continue deployment.
shouldContinueDeployment())
{
};
}

```
To learn how to configure the deployment queue budget, see DeploymentQueueBudget.
To learn how to set the number of threads to use to load resources, see LoadingThreadCount.

### Disabling input handling¶
A Kanzi application handles input by default. To optimize performance, you can disable input handling in an application that does not need it. When you disable input, Kanzi does not spend CPU resources on the input events that it receives from the platform. Keep in mind that when you disable input handling, the application cannot manage the key focus, either.
To disable input handling and key focus management, override the `Application::setScreenOverride` function:  
```
// To disable input handling and key focus management, leave the implementation empty.
void setScreenOverride() override
{
}

```
